def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # A horizontal bar of color 2 divides regions; extend the color above it
    # down through the zero cells, guided by the color marker in the top row.
    divider = next((r for r,row in enumerate(grid) if row and all(x == 2 for x in row)), None)
    if divider is not None:
        for c in range(w):
            color = next((grid[r][c] for r in range(divider) if grid[r][c] != 0), 0)
            if color:
                for r in range(1, divider):
                    if grid[r][c] == 0:
                        out[r][c] = 4
    return out
